#!/usr/bin/env python3
"""Exercise the keepalive script generated by menu.sh without touching WireGuard."""

import os
import pathlib
import signal
import subprocess
import sys
import tempfile
import time
import unittest


ROOT = pathlib.Path(__file__).resolve().parents[1]


class KeepaliveTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory(prefix="warp-keepalive-test-")
        self.root = pathlib.Path(self.tmp.name)
        self.bin = self.root / "bin"
        self.bin.mkdir()
        self.state = self.root / "state"
        self.state.mkdir()
        self.log = self.state / "log"
        self.log.touch()
        self.write("interface", "up")
        self.write("handshake", "990")
        self.write("now", "1000")

        menu = (ROOT / "menu.sh").read_text()
        script = menu.split("cat > /etc/wireguard/keepalive.sh <<'EOF'\n", 1)[1].split("\nEOF\n", 1)[0]
        script = script.replace("LOCK=/var/run/warp-keepalive.lock", f"LOCK={self.root}/lock")
        self.keepalive = self.root / "keepalive.sh"
        self.keepalive.write_text(script + "\n")
        self.keepalive.chmod(0o755)
        self.env = os.environ.copy()
        self.env.update({"PATH": f"{self.bin}:{os.environ['PATH']}", "MOCK_STATE": str(self.state),
                         "KEEPALIVE": str(self.keepalive), "INTERVAL": "0.1",
                         "STOP_HOOK": "pre" if "PreDown = /etc/wireguard/keepalive.sh stop" in menu else "post"})
        self.command("wg", r'''#!/usr/bin/env bash
printf 'wg %s\n' "$*" >> "$MOCK_STATE/log"
case "$*" in
  'show warp') echo "$PPID" > "$MOCK_STATE/loop_pid"; [ -f "$MOCK_STATE/interface" ] ;;
  'show warp latest-handshakes') printf 'peer\t%s\n' "$(cat "$MOCK_STATE/handshake")" ;;
  '') echo "$PPID" > "$MOCK_STATE/loop_pid"; [ -f "$MOCK_STATE/interface" ] && printf 'interface: warp\n' ;;
  *) exit 1 ;;
esac
''')
        self.command("wg-quick", r'''#!/usr/bin/env bash
printf 'quick %s %s\n' "$1" "${WARP_KEEPALIVE_RESTART:-0}" >> "$MOCK_STATE/log"
case "$1" in
  down)
    [ "$STOP_HOOK" = pre ] && "$KEEPALIVE" stop
    rm -f "$MOCK_STATE/interface"
    [ "$STOP_HOOK" = post ] && "$KEEPALIVE" stop
    true
    ;;
  up)
    if [ -f "$MOCK_STATE/fail_up" ]; then
      rm -f "$MOCK_STATE/fail_up"
      "$KEEPALIVE" stop
      exit 1
    fi
    touch "$MOCK_STATE/interface"
    cat "$MOCK_STATE/now" > "$MOCK_STATE/handshake"
    "$KEEPALIVE" start
    ;;
esac
''')
        self.command("warp", "#!/usr/bin/env bash\necho 'warp n' >> \"$MOCK_STATE/log\"\n")
        self.command("date", "#!/usr/bin/env bash\ncat \"$MOCK_STATE/now\"\n")
        if os.environ.get("USE_SYSTEM_PS") != "1":
            self.command("ps", r'''#!/usr/bin/env bash
if [ -f "$MOCK_STATE/loop_pid" ]; then
  if [ "${MOCK_BUSYBOX_PS:-0}" = 1 ]; then
    printf '%s root 0:00 %s loop\n' "$(cat "$MOCK_STATE/loop_pid")" "$KEEPALIVE"
  else
    printf 'test %s 1 0 00:00 ? 00:00:00 %s loop\n' "$(cat "$MOCK_STATE/loop_pid")" "$KEEPALIVE"
  fi
fi
''')
        if os.environ.get("USE_SYSTEM_FLOCK") != "1":
            self.command("flock", f'''#!{sys.executable}
import fcntl, sys
try:
    fcntl.flock(int(sys.argv[-1]), fcntl.LOCK_EX | fcntl.LOCK_NB)
except BlockingIOError:
    sys.exit(1)
''')

    def tearDown(self):
        pidfile = self.state / "loop_pid"
        if pidfile.exists():
            try:
                os.kill(int(pidfile.read_text()), signal.SIGTERM)
            except (ProcessLookupError, ValueError):
                pass
        time.sleep(0.15)
        self.tmp.cleanup()

    def write(self, name, value):
        (self.state / name).write_text(value)

    def command(self, name, body):
        path = self.bin / name
        path.write_text(body)
        path.chmod(0o755)

    def events(self):
        return self.log.read_text().splitlines()

    def wait_for(self, predicate, description, timeout=3):
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if predicate():
                return
            time.sleep(0.02)
        self.fail(f"Timed out waiting for {description}; events: {self.events()}")

    def start(self):
        subprocess.run([str(self.keepalive), "start"], env=self.env, check=True, timeout=7)
        self.wait_for(lambda: (self.state / "loop_pid").exists(), "keepalive loop")

    def test_healthy_interface_is_not_restarted_or_refreshed(self):
        self.start()
        self.wait_for(lambda: len(self.events()) >= 2, "health check")
        time.sleep(0.2)
        self.assertFalse(any(e.startswith(("quick ", "warp ")) for e in self.events()), self.events())

    def test_stale_handshake_restarts_without_stopping_monitor(self):
        self.write("handshake", "700")
        self.start()
        self.wait_for(lambda: "quick up 1" in self.events(), "restart after stale handshake")
        self.wait_for(lambda: self.events().count("wg show warp") >= 2, "monitor after restart")
        self.assertIn("quick down 1", self.events())
        self.assertNotIn("warp n", self.events())

    def test_missing_interface_is_restored_and_failed_up_is_retried(self):
        self.start()
        self.write("fail_up", "1")
        (self.state / "interface").unlink()
        self.wait_for(lambda: self.events().count("quick up 1") >= 2 and
                      (self.state / "interface").exists(), "retry after failed up")
        self.wait_for(lambda: self.events().count("wg show warp") >= 3, "monitor after recovery")

    def test_first_handshake_has_a_grace_period_then_is_retried(self):
        self.write("handshake", "0")
        self.start()
        self.wait_for(lambda: self.events().count("wg show warp") >= 2, "initial zero handshake check")
        self.assertFalse(any(e.startswith("quick ") for e in self.events()), self.events())
        self.write("now", "1181")
        self.wait_for(lambda: "quick up 1" in self.events(), "retry after handshake grace period")

    def test_manual_shutdown_stops_monitor(self):
        self.start()
        subprocess.run([str(self.bin / "wg-quick"), "down", "warp"], env=self.env, check=True, timeout=5)
        self.wait_for(lambda: "quick down 0" in self.events(), "manual shutdown")
        time.sleep(0.4)
        self.assertFalse((self.state / "interface").exists(), self.events())
        self.assertFalse(any(e.startswith("quick up") for e in self.events()), self.events())

    def test_busybox_ps_can_stop_monitor(self):
        if os.environ.get("USE_SYSTEM_PS") == "1":
            self.skipTest("requires the BusyBox ps mock")
        self.env["MOCK_BUSYBOX_PS"] = "1"
        self.test_manual_shutdown_stops_monitor()


if __name__ == "__main__":
    unittest.main(verbosity=2)
